"""ES256 签名与规范化 JSON。

ES256 即 ECDSA over P-256 与 SHA-256。签名以 JWS 约定编码：
64 字节裸 R||S 的 base64url（无填充）。cryptography 库签出的是 DER，
这里在 DER 与 R||S 之间做转换。
"""

import base64
import json
import re
from typing import Any, Dict

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import ec
from cryptography.hazmat.primitives.asymmetric.utils import (
    decode_dss_signature,
    encode_dss_signature,
)

__all__ = [
    "InvalidSignature",
    "MalformedSignature",
    "canonicalize",
    "generate_private_key_pem",
    "public_key_pem_from_private",
    "validate_public_key_pem",
    "validate_signature_format",
    "validate_signature_format_strict",
    "sign",
    "verify",
]


class MalformedSignature(ValueError):
    """签名编码格式非法（无法解码或不是 64 字节裸 R||S）。"""


def _b64url(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")


def _b64url_decode(text: str) -> bytes:
    padding = "=" * (-len(text) % 4)
    return base64.urlsafe_b64decode(text + padding)


def canonicalize(body: Dict[str, Any]) -> bytes:
    """正文按 key 升序的规范化 JSON 序列化（紧凑、UTF-8 字节）。"""
    return json.dumps(
        body, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")


def generate_private_key_pem() -> str:
    """生成 P-256 私钥，返回 PKCS8 PEM 字符串。"""
    private_key = ec.generate_private_key(ec.SECP256R1())
    pem = private_key.private_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PrivateFormat.PKCS8,
        encryption_algorithm=serialization.NoEncryption(),
    )
    return pem.decode("utf-8")


def public_key_pem_from_private(private_pem: str) -> str:
    """从私钥 PEM 导出对应的 SubjectPublicKeyInfo 公钥 PEM。"""
    private_key = serialization.load_pem_private_key(
        private_pem.encode("utf-8"), password=None
    )
    if not isinstance(private_key, ec.EllipticCurvePrivateKey):
        raise ValueError("私钥不是 P-256 椭圆曲线私钥")
    if not isinstance(private_key.curve, ec.SECP256R1):
        raise ValueError("私钥曲线不是 P-256")
    pem = private_key.public_key().public_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PublicFormat.SubjectPublicKeyInfo,
    )
    return pem.decode("utf-8")


def _load_public_key(public_pem: str) -> ec.EllipticCurvePublicKey:
    try:
        key = serialization.load_pem_public_key(public_pem.encode("utf-8"))
    except (ValueError, TypeError) as exc:
        raise ValueError(f"公钥 PEM 无法解析: {exc}") from exc
    if not isinstance(key, ec.EllipticCurvePublicKey) or not isinstance(
        key.curve, ec.SECP256R1
    ):
        raise ValueError("公钥不是 P-256 椭圆曲线公钥")
    return key


def validate_public_key_pem(public_pem: str) -> None:
    """校验公钥 PEM 可解析且为 ES256 所需的 P-256 公钥，否则抛 ValueError。"""
    _load_public_key(public_pem)


def _load_private_key(private_pem: str) -> ec.EllipticCurvePrivateKey:
    try:
        key = serialization.load_pem_private_key(
            private_pem.encode("utf-8"), password=None
        )
    except (ValueError, TypeError) as exc:
        raise ValueError(f"私钥 PEM 无法解析: {exc}") from exc
    if not isinstance(key, ec.EllipticCurvePrivateKey) or not isinstance(
        key.curve, ec.SECP256R1
    ):
        raise ValueError("私钥不是 P-256 椭圆曲线私钥")
    return key


def sign(body: Dict[str, Any], private_pem: str) -> str:
    """对规范化正文做 ES256 签名，返回 base64url(R||S)。"""
    private_key = _load_private_key(private_pem)
    der = private_key.sign(
        canonicalize(body), ec.ECDSA(hashes.SHA256())
    )
    r, s = decode_dss_signature(der)
    raw = r.to_bytes(32, "big") + s.to_bytes(32, "big")
    return _b64url(raw)


def validate_signature_format(signature_b64: str) -> None:
    """校验签名编码格式：须为可解码的 base64url 且裸 R||S 恰为 64 字节。

    仅检查格式，不做密码学验签。格式非法抛 MalformedSignature。
    """
    try:
        raw = _b64url_decode(signature_b64)
    except Exception as exc:  # noqa: BLE001 解码异常（含 binascii）均属格式问题
        raise MalformedSignature("签名不是合法的 base64url 编码") from exc
    if len(raw) != 64:
        raise MalformedSignature("签名长度不是 64 字节，非合法 ES256 签名")


# 严格格式：64 字节裸 R||S 的无填充 base64url 恰为 86 个字符
_RAW_RS_B64URL_STRICT_RE = re.compile(r"[A-Za-z0-9_-]{86}")


def validate_signature_format_strict(signature_b64: str) -> None:
    """严格校验签名编码格式：恰为 86 个 base64url 字符（无填充、无字
    母表外字符），解码恰为 64 字节裸 R||S，且无填充 base64url 重编码
    与原文逐字符一致（排除填充与非规范尾位）。

    仅检查格式，不做密码学验签。格式非法抛 MalformedSignature。
    """
    if not isinstance(signature_b64, str) or not (
        _RAW_RS_B64URL_STRICT_RE.fullmatch(signature_b64)
    ):
        raise MalformedSignature(
            "签名不是 86 字符的无填充 base64url 编码"
        )
    raw = _b64url_decode(signature_b64)
    if len(raw) != 64 or _b64url(raw) != signature_b64:
        raise MalformedSignature(
            "签名不是规范的 64 字节裸 R||S 无填充 base64url 编码"
        )


def verify(body: Dict[str, Any], signature_b64: str, public_pem: str) -> None:
    """校验签名：格式非法抛 MalformedSignature，验签失败抛 InvalidSignature。"""
    validate_signature_format(signature_b64)
    public_key = _load_public_key(public_pem)
    raw = _b64url_decode(signature_b64)
    r = int.from_bytes(raw[:32], "big")
    s = int.from_bytes(raw[32:], "big")
    der = encode_dss_signature(r, s)
    public_key.verify(der, canonicalize(body), ec.ECDSA(hashes.SHA256()))

        return self._presentation_record(row)

def verify_presentation(
    self,
    tenant_id: str,
    presentation_id: str,
    presentation: Any,
    challenge: Any = CHALLENGE_UNSET,
) -> Tuple[bool, str]:
    """以存储记录为锚校验选择性披露演示，返回 (是否有效, 失败原因)。

    校验顺序：请求 -> 资源 ID -> 绑定（含 challenge）-> 已消费 ->
    过期（当前时间 >= expires_at）-> 投影 -> proof 格式与签名 ->
    吊销。新演示（存储记录含 challenge）要求请求恰含 presentation
    与 challenge，且请求 challenge、演示 challenge 与 proof 覆盖的
    存储 challenge 三者一致；旧演示（无 challenge）只接受恰含
    presentation 的请求，不做挑战、过期与消费检查。

    验签成功后在消费锁内复查已消费/到期/暂停/吊销：复查到期即返回
    “演示已过期”，不消费、不记审计；未到期并发验证仅一次成功，
    成功时原子标记已消费并记一次 presentation.consumed（标记与
    事件同一次原子写，失败回滚不记），跨重启保留；已消费优先于
    过期与吊销/暂停；签名成功但已暂停返回“凭证已暂停：<原因>”、
    已吊销返回“凭证已吊销：<原因>”，均不消费。任何失败均返回非空
    中文原因，绝不抛异常、不泄露私钥。
    """
    if not isinstance(presentation, dict):
        return False, "请求不合法: 字段 presentation 必须为 JSON 对象"

    with self._lock:
        bucket = self._bucket_locked(tenant_id)
        row = (
            bucket["presentations"].get(presentation_id)
            if bucket is not None else None
        )
        if row is None:
            return False, f"演示不存在: {presentation_id}"

        # 新/旧演示按存储记录是否含 challenge 判定
        is_replay_protected = "challenge" in row
        # 持有者绑定演示按存储记录是否含 holder_did 判定（绑定演示
        # 一定也是防重放新演示）。
        is_holder_bound = "holder_did" in row
        if is_replay_protected:
            if challenge is CHALLENGE_UNSET:
                return False, "请求缺少字段: challenge"
        elif challenge is not CHALLENGE_UNSET:
            return False, "请求含多余字段: challenge"

        expected_keys = {
            "presentation_id",
            "credential_id",
            "issuer_did",
            "issuer_key_version",
            "disclose",
            "claims",
            "proof",
        }
        if is_replay_protected:
            expected_keys |= {"challenge", "expires_at"}
        if is_holder_bound:
            expected_keys |= {
                "holder_did",
                "holder_key_version",
                "holder_proof",
            }
        if set(presentation) != expected_keys:
            return False, (
                "锚定校验失败: presentation 字段集合与存储记录不一致"
            )
        proof = presentation.get("proof")
        if not isinstance(proof, str) or not proof:
            return False, "请求不合法: 字段 proof 必须为非空字符串"
        if presentation.get("presentation_id") != presentation_id:
            return False, (
                "锚定校验失败: presentation_id 与路径或存储记录不一致"
            )
        if presentation.get("credential_id") != row.get("credential_id"):
            return False, (
                "锚定校验失败: credential_id 与存储记录不一致"
            )
        if presentation.get("issuer_did") != row.get("issuer_did"):
            return False, "锚定校验失败: issuer_did 与存储记录不一致"
        stored_version = int(row.get("issuer_key_version", 1))
        version_obj = presentation.get("issuer_key_version")
        if (
            not isinstance(version_obj, int)
            or isinstance(version_obj, bool)
            or version_obj != stored_version
        ):
            return False, (
                "锚定校验失败: issuer_key_version 与存储记录不一致"
            )
        if presentation.get("disclose") != list(row.get("disclose", [])):
            return False, "锚定校验失败: disclose 与存储记录不一致"

        if is_holder_bound:
            # holder 字段与存储记录逐一锚定；holder_proof 还须为
            # 非空字符串（holder_did 必须等于凭证 subject_did 的
            # 进一步绑定在生成时已保证，此处再与存储行核对）。
            if presentation.get("holder_did") != row.get("holder_did"):
                return False, (
                    "锚定校验失败: holder_did 与存储记录不一致"
                )
            stored_holder_version = row.get("holder_key_version")
            holder_version_obj = presentation.get("holder_key_version")
            if (
                not isinstance(holder_version_obj, int)
                or isinstance(holder_version_obj, bool)
                or holder_version_obj != stored_holder_version
            ):
                return False, (
                    "锚定校验失败: holder_key_version 与存储记录不一致"
                )
            holder_proof = presentation.get("holder_proof")
            if not isinstance(holder_proof, str) or not holder_proof:
                return False, (
                    "请求不合法: 字段 holder_proof 必须为非空字符串"
                )

        if is_replay_protected:
            # 请求 challenge、演示 challenge 与 proof 覆盖的存储
            # challenge 三者必须一致
            stored_challenge = row.get("challenge")
            if presentation.get("challenge") != stored_challenge:
                return False, (
                    "锚定校验失败: challenge 与存储记录不一致"
                )
            if challenge != stored_challenge:
                return False, (
                    "锚定校验失败: 请求 challenge 与存储记录不一致"
                )
            if presentation.get("expires_at") != row.get("expires_at"):
                return False, (
                    "锚定校验失败: expires_at 与存储记录不一致"
                )
            # 已消费优先于过期与吊销
            if row.get("consumed"):
                return False, "演示已消费"
            try:
                expires_at = _parse_utc_z(row["expires_at"])
            except (KeyError, TypeError, ValueError):
                return False, "验签过程发生内部错误"
            if datetime.now(timezone.utc) >= expires_at:
                return False, "演示已过期"

        obj_claims = presentation.get("claims")
        if not isinstance(obj_claims, dict):
            return False, "请求不合法: 演示 claims 必须为 JSON 对象"

        credential_id = row["credential_id"]
        issuer_did = row["issuer_did"]
        cred = bucket["credentials"].get(credential_id)
        if cred is None:
            return False, f"凭证不存在: {credential_id}"
        source_claims = cred["body"].get("claims", {})
        credential_status = cred.get("status")
        revoke_reason = cred.get("revoke_reason")
        suspend_reason = cred.get("suspend_reason")
        credential_expires_at = cred["body"].get("expires_at")

        public_pem = self._public_key_for_version_locked(
            bucket, issuer_did, stored_version
        )
        issuer_entry = self._key_history_entry_by_version_locked(
            bucket, issuer_did, stored_version
        )
        issuer_key_revoked = (
            issuer_entry is not None
            and issuer_entry.get("status") == "revoked"
        )
        issuer_key_revoke_reason = (
            issuer_entry.get("revoke_reason")
            if issuer_entry is not None
            else None
        )
        # 签发者 DID 停用状态在锚定与双签名成功后判定；锁内捕获。
        issuer_did_row = bucket["dids"].get(issuer_did)
        issuer_did_deactivated = self._is_did_deactivated_locked(
            issuer_did_row
        )
        issuer_did_deactivate_reason = (
            issuer_did_row.get("deactivate_reason")
            if issuer_did_row is not None
            else None
        )

        # 持有者绑定：holder_did 必须等于凭证正文 subject_did，且
        # 持有者为本租户已注册 DID，按 holder_key_version 从其公钥
        # 历史中取历史公钥（轮换后仍可验证；公钥缺失则判密钥不可用）。
        holder_did_value: Optional[str] = None
        holder_version_value: Optional[int] = None
        holder_public_pem: Optional[str] = None
        holder_key_revoked = False
        holder_key_revoke_reason: Optional[str] = None
        if is_holder_bound:
            holder_did_value = row.get("holder_did")
            subject_did = cred["body"].get("subject_did")
            if holder_did_value != subject_did:
                return False, (
                    "锚定校验失败: holder_did 与凭证 subject_did 不一致"
                )
            holder_rec = bucket["dids"].get(holder_did_value)
            if holder_rec is None:
                return False, (
                    f"持有者 DID 不存在: {holder_did_value}"
                )
            holder_version_value = int(
                row.get("holder_key_version", 0)
            )
            holder_public_pem = self._public_key_for_version_locked(
                bucket, holder_did_value, holder_version_value
            )
            holder_entry = self._key_history_entry_by_version_locked(
                bucket, holder_did_value, holder_version_value
            )
            holder_key_revoked = (
                holder_entry is not None
                and holder_entry.get("status") == "revoked"
            )
            holder_key_revoke_reason = (
                holder_entry.get("revoke_reason")
                if holder_entry is not None
                else None
            )

    # 按存储的 disclose 从存储凭证 claims 重算投影并核对
    stored_disclose = list(row.get("disclose", []))
    try:
        parsed_stored = [
            (pointer, _parse_pointer(pointer))
            for pointer in stored_disclose
        ]
        recomputed = _project_claims(source_claims, parsed_stored)
    except ValidationError as exc:
        return False, f"投影重算失败: {exc}"
    if obj_claims != recomputed:
        return False, (
            "锚定校验失败: claims 投影与按存储凭证重算的结果不一致"
        )

    if not public_pem:
        return False, (
            "历史公钥不可用: 签发者 "
            f"{issuer_did} 密钥版本 {stored_version} 的公钥不存在"
        )
    try:
        crypto.validate_public_key_pem(public_pem)
    except (ValueError, TypeError):
        return False, (
            "历史公钥不可用: 签发者 "
            f"{issuer_did} 密钥版本 {stored_version} 的公钥无法解析"
        )

    unsigned = {
        "presentation_id": presentation_id,
        "credential_id": credential_id,
        "issuer_did": issuer_did,
        "issuer_key_version": stored_version,
        "disclose": list(row.get("disclose", [])),
        "claims": recomputed,
    }
    if is_replay_protected:
        unsigned["challenge"] = row.get("challenge")
        unsigned["expires_at"] = row.get("expires_at")
    try:
        crypto.verify(unsigned, proof, public_pem)
    except crypto.MalformedSignature:
        return False, "签名格式错误: 不是合法的 ES256 签名编码"
    except crypto.InvalidSignature:
        return False, "签名校验失败，演示内容或 proof 可能被改动"
    except Exception:  # noqa: BLE001 验签绝不向上抛错或泄露内部细节
        return False, "验签过程发生内部错误"

    # issuer proof 验签成功后检查签发密钥版本是否已吊销（优先于
    # 持有者校验、凭证有效期与凭证吊销）。
    if issuer_key_revoked:
        saved_reason = (
            issuer_key_revoke_reason or DEFAULT_KEY_REVOKE_REASON
        )
        return False, f"签发密钥已吊销：{saved_reason}"

    # 双签名锚定的 issuer 侧已通过：签发者 DID 已停用则 valid:false，
    # 优先于持有者校验、凭证有效期与凭证吊销（只读，不消费）。
    if issuer_did_deactivated:
        saved_reason = (
            issuer_did_deactivate_reason
            or DEFAULT_DID_DEACTIVATE_REASON
        )
        return False, f"{DID_DEACTIVATED_REASON_PREFIX}{saved_reason}"

    if is_holder_bound:
        # 持有者第二签名：覆盖去掉 proof、holder_proof 后的完整演示
        # 对象（此处与 issuer proof 覆盖对象同构，另含 holder_did、
        # holder_key_version）及 tenant_id，按规范化 JSON/UTF-8 验签；
        # 公钥按 holder_key_version 取持有者历史公钥，轮换后仍可验证。
        if not holder_public_pem:
            return False, (
                "历史公钥不可用: 持有者 "
                f"{holder_did_value} 密钥版本 "
                f"{holder_version_value} 的公钥不存在"
            )
        try:
            crypto.validate_public_key_pem(holder_public_pem)
        except (ValueError, TypeError):
            return False, (
                "历史公钥不可用: 持有者 "
                f"{holder_did_value} 密钥版本 "
                f"{holder_version_value} 的公钥无法解析"
            )
        holder_unsigned = dict(unsigned)
        holder_unsigned["holder_did"] = holder_did_value
        holder_unsigned["holder_key_version"] = holder_version_value
        holder_unsigned["tenant_id"] = tenant_id
        try:
            crypto.verify(
                holder_unsigned, holder_proof, holder_public_pem
            )
        except crypto.MalformedSignature:
            return False, (
                "签名格式错误: holder_proof 不是合法的 ES256 签名编码"
            )
        except crypto.InvalidSignature:
            return False, (
                "签名校验失败: holder_proof 与持有者历史公钥不匹配，"
                "持有者绑定内容可能被改动"
            )
        except Exception:  # noqa: BLE001 验签绝不向上抛错
            return False, "验签过程发生内部错误"

        # 持有者 proof 验签成功后检查持有者密钥版本是否已吊销
        # （优先于凭证有效期与凭证吊销）。
        if holder_key_revoked:
            saved_reason = (
                holder_key_revoke_reason or DEFAULT_KEY_REVOKE_REASON
            )
            return False, f"持有者密钥已吊销：{saved_reason}"

    # 签名与锚定均成功后检查凭证有效期：凭证已到期直接拒绝，不消费
    if _is_expired(credential_expires_at):
        return False, CREDENTIAL_EXPIRED_REASON

    # 签名与锚定均成功后检查凭证状态：已暂停/已吊销不消费，判定
    # 位置相同（有效期之后、消费之前）；暂停返回保存的暂停原因，
    # 恢复后可再次正常使用。
    if credential_status == "suspended":
        saved_reason = suspend_reason or "未知原因"
        return False, f"{CREDENTIAL_SUSPENDED_REASON_PREFIX}{saved_reason}"
    if credential_status == "revoked":
        saved_reason = revoke_reason or DEFAULT_REVOKE_REASON
        return False, f"凭证已吊销：{saved_reason}"

    if is_replay_protected:
        # 原子标记已消费：消费锁内复查已消费/到期/吊销，防止
        # “锁外验签期间演示到期仍被消费”的竞态。并发仅一次成功，
        # 跨重启保留；复查到期或已吊销均不消费、不记审计。
        with self._lock:
            bucket = self._bucket_locked(tenant_id)
            row = (
                bucket["presentations"].get(presentation_id)
                if bucket is not None else None
            )
            if row is None:
                return False, f"演示不存在: {presentation_id}"
            if row.get("consumed"):
                return False, "演示已消费"
            try:
                expires_at = _parse_utc_z(row["expires_at"])
            except (KeyError, TypeError, ValueError):
                return False, "验签过程发生内部错误"
            if datetime.now(timezone.utc) >= expires_at:
                return False, "演示已过期"
            cred = bucket["credentials"].get(credential_id)
            # 锁内复查密钥版本吊销状态（防锁外验签期间被吊销的竞态）：
            # 签发密钥优先于持有者密钥，二者均优先于凭证有效期/吊销。
            issuer_entry_now = self._key_history_entry_by_version_locked(
                bucket, issuer_did, stored_version
            )
            if (
                issuer_entry_now is not None
                and issuer_entry_now.get("status") == "revoked"
            ):
                saved_reason = (
                    issuer_entry_now.get("revoke_reason")
                    or DEFAULT_KEY_REVOKE_REASON
                )
                return False, f"签发密钥已吊销：{saved_reason}"
            # 锁内复查签发者 DID 停用状态（防锁外验签期间被停用的
            # 竞态）：停用不消费，优先于有效期/凭证吊销。
            issuer_row_now = bucket["dids"].get(issuer_did)
            if self._is_did_deactivated_locked(issuer_row_now):
                saved_reason = (
                    issuer_row_now.get("deactivate_reason")
                    or DEFAULT_DID_DEACTIVATE_REASON
                )
                return False, (
                    f"{DID_DEACTIVATED_REASON_PREFIX}{saved_reason}"
                )
            if is_holder_bound and holder_did_value is not None:
                holder_entry_now = (
                    self._key_history_entry_by_version_locked(
                        bucket,
                        holder_did_value,
                        holder_version_value,
                    )
                )
                if (
                    holder_entry_now is not None
                    and holder_entry_now.get("status") == "revoked"
                ):
                    saved_reason = (
                        holder_entry_now.get("revoke_reason")
                        or DEFAULT_KEY_REVOKE_REASON
                    )
                    return False, f"持有者密钥已吊销：{saved_reason}"
            if cred is not None and _is_expired(
                cred["body"].get("expires_at")
            ):
                return False, CREDENTIAL_EXPIRED_REASON
            if cred is not None and cred.get("status") == "suspended":

with self._lock:
    bucket = self._bucket_locked(tenant_id)
    row = (
        bucket.get("multi_presentations", {}).get(presentation_id)
        if bucket is not None else None
    )
    if row is None:
        return False, f"演示不存在: {presentation_id}"

    is_holder_bound = "holder_did" in row
    expected_keys = {
        "presentation_id",
        "items",
        "challenge",
        "expires_at",
    }
    if is_holder_bound:
        expected_keys |= {
            "holder_did",
            "holder_key_version",
            "holder_proof",
        }
    if set(presentation) != expected_keys:
        return False, "字段集不一致"
    if presentation.get("presentation_id") != presentation_id:
        return False, "锚定校验失败"
    if challenge is CHALLENGE_UNSET:
        return False, "字段集不一致"
    stored_challenge = row.get("challenge")
    if presentation.get("challenge") != stored_challenge:
        return False, "锚定校验失败"
    if challenge != stored_challenge:
        return False, "锚定校验失败"
    if presentation.get("expires_at") != row.get("expires_at"):
        return False, "锚定校验失败"
    # 已消费优先于过期与各凭证状态
    if row.get("consumed"):
        return False, "展示已消费"
    try:
        expires_at = _parse_utc_z(row["expires_at"])
    except (KeyError, TypeError, ValueError):
        return False, "验签过程发生内部错误"
    if datetime.now(timezone.utc) >= expires_at:
        return False, "展示已过期"

    if is_holder_bound:
        if presentation.get("holder_did") != row.get("holder_did"):
            return False, "锚定校验失败"
        stored_holder_version = row.get("holder_key_version")
        holder_version_obj = presentation.get("holder_key_version")
        if (
            not isinstance(holder_version_obj, int)
            or isinstance(holder_version_obj, bool)
            or holder_version_obj != stored_holder_version
        ):
            return False, "锚定校验失败"
        holder_proof = presentation.get("holder_proof")
        if not isinstance(holder_proof, str) or not holder_proof:
            return False, "字段集不一致"

    obj_items = presentation.get("items")
    stored_items = list(row.get("items", []))
    if not isinstance(obj_items, list) or len(obj_items) != len(
        stored_items
    ):
        return False, "字段集不一致"
    item_expected_keys = {
        "credential_id",
        "issuer_did",
        "issuer_key_version",
        "disclose",
        "claims",
        "proof",
    }
    obj_claims_list: List[Dict[str, Any]] = []
    for obj_item, stored_item in zip(obj_items, stored_items):
        if not isinstance(obj_item, dict):
            return False, "字段集不一致"
        if set(obj_item) != item_expected_keys:
            return False, "字段集不一致"
        if (
            obj_item.get("credential_id")
            != stored_item.get("credential_id")
        ):
            return False, "锚定校验失败"
        if obj_item.get("issuer_did") != stored_item.get("issuer_did"):
            return False, "锚定校验失败"
        stored_version = int(
            stored_item.get("issuer_key_version", 1)
        )
        version_obj = obj_item.get("issuer_key_version")
        if (
            not isinstance(version_obj, int)
            or isinstance(version_obj, bool)
            or version_obj != stored_version
        ):
            return False, "锚定校验失败"
        if obj_item.get("disclose") != list(
            stored_item.get("disclose", [])
        ):
            return False, "锚定校验失败"
        proof = obj_item.get("proof")
        if not isinstance(proof, str) or not proof:
            return False, "字段集不一致"
        obj_claims = obj_item.get("claims")
        if not isinstance(obj_claims, dict):
            return False, "字段集不一致"
        obj_claims_list.append(obj_claims)

    # 锁内收集各凭证当前状态与重算投影所需数据
    credential_contexts: List[Dict[str, Any]] = []
    for stored_item, obj_claims in zip(stored_items, obj_claims_list):
        credential_id = stored_item["credential_id"]
        issuer_did = stored_item["issuer_did"]
        stored_version = int(
            stored_item.get("issuer_key_version", 1)
        )
        cred = bucket["credentials"].get(credential_id)
        if cred is None:
            return False, f"凭证不存在: {credential_id}"
        source_claims = cred["body"].get("claims", {})
        stored_disclose = list(stored_item.get("disclose", []))
        try:
            parsed_stored = [
                (pointer, _parse_pointer(pointer))
                for pointer in stored_disclose
            ]
            recomputed = _project_claims(source_claims, parsed_stored)
        except ValidationError:
            return False, "锚定校验失败"
        if obj_claims != recomputed:
            return False, "锚定校验失败"
        public_pem = self._public_key_for_version_locked(
            bucket, issuer_did, stored_version
        )
        credential_contexts.append(
            {
                "credential_id": credential_id,
                "issuer_did": issuer_did,
                "version": stored_version,
                "public_pem": public_pem,
                "cred": cred,
            }
        )

# 锁外逐项验证签发证明：格式或密码学失败统一为“签名校验失败”。
# 按存储项与存储凭证 claims 重算投影组装被签名正文，与各凭证
# 签发密钥版本的历史公钥验签。
for index, (ctx, stored_item) in enumerate(
    zip(credential_contexts, stored_items)
):
    cred = ctx["cred"]
    source_claims = cred["body"].get("claims", {})
    stored_disclose = list(stored_item.get("disclose", []))
    parsed_stored = [
        (pointer, _parse_pointer(pointer))
        for pointer in stored_disclose
    ]
    recomputed = _project_claims(source_claims, parsed_stored)
    unsigned_item = {
        "presentation_id": presentation_id,
        "credential_id": stored_item["credential_id"],
        "issuer_did": stored_item["issuer_did"],
        "issuer_key_version": int(
            stored_item.get("issuer_key_version", 1)
        ),
        "disclose": stored_disclose,
        "claims": recomputed,
        "challenge": row.get("challenge"),
        "expires_at": row.get("expires_at"),
    }
    try:
        crypto.verify(
            unsigned_item,
            obj_items[index]["proof"],
            ctx["public_pem"],
        )
    except Exception:  # noqa: BLE001 格式/验签失败统一分类
        return False, "签名校验失败"

# 签发密钥吊销 / 签发者 DID 停用（未列入固定原因的失败沿用
# 单凭证演示的中文语义，不消费）。
with self._lock:
    bucket_now = self._bucket_locked(tenant_id)
    if bucket_now is None:
        return False, f"演示不存在: {presentation_id}"
    for ctx in credential_contexts:
        issuer_entry = self._key_history_entry_by_version_locked(
            bucket_now, ctx["issuer_did"], ctx["version"]
        )
        if (
            issuer_entry is not None
            and issuer_entry.get("status") == "revoked"
        ):
            saved_reason = (
                issuer_entry.get("revoke_reason")
                or DEFAULT_KEY_REVOKE_REASON
            )
            return False, f"签发密钥已吊销：{saved_reason}"
        issuer_row = bucket_now["dids"].get(ctx["issuer_did"])
        if self._is_did_deactivated_locked(issuer_row):
            saved_reason = (
                issuer_row.get("deactivate_reason")
                or DEFAULT_DID_DEACTIVATE_REASON
            )
            return False, (
                f"{DID_DEACTIVATED_REASON_PREFIX}{saved_reason}"
            )

    if is_holder_bound:
        holder_did_value = row.get("holder_did")
        # holder_did 必须等于组合内每张凭证正文的 subject_did
        for ctx in credential_contexts:
            subject_did = ctx["cred"]["body"].get("subject_did")
            if holder_did_value != subject_did:
                return False, "持有人绑定失败"
        holder_version_value = int(row.get("holder_key_version", 0))
        holder_rec = bucket_now["dids"].get(holder_did_value)
        if holder_rec is None:
            return False, "持有人绑定失败"
        holder_public_pem = self._public_key_for_version_locked(
            bucket_now, holder_did_value, holder_version_value
        )
        if not holder_public_pem:
            return False, "持有人绑定失败"
        holder_entry = self._key_history_entry_by_version_locked(
            bucket_now, holder_did_value, holder_version_value
        )
        if (
            holder_entry is not None
            and holder_entry.get("status") == "revoked"
        ):
            return False, "持有人绑定失败"
        try:
            crypto.validate_public_key_pem(holder_public_pem)
        except (ValueError, TypeError):
            return False, "持有人绑定失败"
        holder_unsigned = self._multi_holder_payload_locked(row)
        holder_unsigned["holder_did"] = holder_did_value
        holder_unsigned["holder_key_version"] = holder_version_value
        holder_unsigned["tenant_id"] = tenant_id
        try:
            crypto.verify(
                holder_unsigned,
                presentation["holder_proof"],
                holder_public_pem,
            )
        except Exception:  # noqa: BLE001 绑定失败统一分类
            return False, "持有人绑定失败"

# 各凭证当前状态按 items 顺序、逐凭证按 已过期 → 已停用 →
# 已吊销 的优先级判定（与单凭证演示一致），失败均不消费。
for ctx in credential_contexts:
    cred = ctx["cred"]
    if _is_expired(cred["body"].get("expires_at")):
        return False, "凭证已过期"
    if cred.get("status") == "suspended":
        return False, "凭证已停用"
    if cred.get("status") == "revoked":
        return False, "凭证已吊销"

# 原子消费：消费锁内复查已消费/展示到期/各凭证状态，任一失败
# 均不消费、不记审计；通过则标记与审计同次原子写。
with self._lock:
    bucket = self._bucket_locked(tenant_id)
    row = (
        bucket.get("multi_presentations", {}).get(presentation_id)
        if bucket is not None else None
    )
    if row is None:
        return False, f"演示不存在: {presentation_id}"
    if row.get("consumed"):
        return False, "展示已消费"
    try:
        expires_at = _parse_utc_z(row["expires_at"])
    except (KeyError, TypeError, ValueError):
        return False, "验签过程发生内部错误"
    if datetime.now(timezone.utc) >= expires_at:
        return False, "展示已过期"
    # 锁内复查各凭证签发密钥/签发者 DID 与凭证状态（防锁外
    # 验签期间发生变更的竞态），逐凭证按 签发密钥 → 签发者
    # DID → 凭证过期/暂停/吊销 的优先级，失败均不消费。
    for stored_item in row.get("items", []):
        credential_id = stored_item["credential_id"]
        issuer_did = stored_item["issuer_did"]
        version = int(stored_item.get("issuer_key_version", 1))
        cred = bucket["credentials"].get(credential_id)
        if cred is None:
            return False, f"凭证不存在: {credential_id}"
        issuer_entry_now = self._key_history_entry_by_version_locked(
            bucket, issuer_did, version
        )
        if (
            issuer_entry_now is not None
            and issuer_entry_now.get("status") == "revoked"
        ):
            saved_reason = (
                issuer_entry_now.get("revoke_reason")
                or DEFAULT_KEY_REVOKE_REASON
            )
            return False, f"签发密钥已吊销：{saved_reason}"
        issuer_row_now = bucket["dids"].get(issuer_did)
        if self._is_did_deactivated_locked(issuer_row_now):
            saved_reason = (
                issuer_row_now.get("deactivate_reason")
                or DEFAULT_DID_DEACTIVATE_REASON
            )
            return False, (
                f"{DID_DEACTIVATED_REASON_PREFIX}{saved_reason}"
            )
        if _is_expired(cred["body"].get("expires_at")):
            return False, "凭证已过期"
        if cred.get("status") == "suspended":
            return False, "凭证已停用"
        if cred.get("status") == "revoked":
            return False, "凭证已吊销"
    if is_holder_bound:
        holder_entry_now = (
            self._key_history_entry_by_version_locked(
                bucket,
                row.get("holder_did"),
                int(row.get("holder_key_version", 0)),
            )
        )
        if (
            holder_entry_now is not None
            and holder_entry_now.get("status") == "revoked"
        ):
            return False, "持有人绑定失败"
    snapshot = self._snapshot_locked()
    try:
        row["consumed"] = True
        row["consumed_at"] = _utc_now()
        self._append_audit_locked(
            tenant_id, AUDIT_PRESENTATION_CONSUMED,
            "presentation", presentation_id,
        )
        self._save_locked()
    except Exception:
        self._restore_locked(snapshot)

def _post_prove(self, tenant: str, credential_id: str) -> None:
    # 请求体必须恰为 {"predicates": [...]} 加可选 challenge、
    # expires_in：缺失/空 predicates、元素字段或 op 非法、路径
    # 重复或祖先重叠、多余字段一律 400；未知凭证 404。
    # challenge 须为非空字符串且按 Unicode 码点不超过 256，
    # 缺省生成 32 位小写 hex；expires_in 须为非布尔整数且
    # 在 1..86400 之间，缺省 300。成功 201 返回证明记录。
    data = self._read_json()
    if "predicates" not in data:
        raise ValidationError("缺少字段: predicates")
    extra = sorted(set(data) - {"predicates", "challenge", "expires_in"})
    if extra:
        raise ValidationError(f"多余字段: {', '.join(extra)}")
    challenge = None
    if "challenge" in data:
        challenge = data["challenge"]
        if not isinstance(challenge, str) or not challenge:
            raise ValidationError("字段 challenge 必须为非空字符串")
        if len(challenge) > 256:
            raise ValidationError(
                "字段 challenge 按 Unicode 码点不能超过 256"
            )
    expires_in = None
    if "expires_in" in data:
        expires_in = data["expires_in"]
        if not isinstance(expires_in, int) or isinstance(
            expires_in, bool
        ):
            raise ValidationError("字段 expires_in 必须为整数")
        if not 1 <= expires_in <= 86400:
            raise ValidationError(
                "字段 expires_in 须在 1 到 86400 之间"
            )
    record = store.create_proof(
        tenant,
        credential_id,
        data["predicates"],
        challenge=challenge,
        expires_in=expires_in,
    )
    self._send_json(201, self._proof_payload(record))

@staticmethod
def _proof_payload(record: Any) -> Dict[str, Any]:
    return {
        "proof_id": record.proof_id,
        "credential_id": record.credential_id,
        "issuer_did": record.issuer_did,
        "issuer_key_version": record.issuer_key_version,
        "predicates": record.predicates,
        "results": record.results,
        "challenge": record.challenge,
        "expires_at": record.expires_at,
        "proof": record.proof,
    }

@staticmethod
def _validate_prove_item(
    item: Any, index: int
) -> Dict[str, Any]:
    """校验单个谓词证明生成项，返回透传给 store 的关键字参数。

    规则与单项 prove 的请求级校验完全一致：项须为对象，恰含
    predicates 及可选 challenge、expires_in；challenge 为非空
    字符串且按 Unicode 码点不超过 256；expires_in 为非布尔整数
    且在 1..86400。predicates 的结构、路径、运算与数值语义在
    store 内结合凭证 claims 校验，与单项 prove 完全一致。
    index 为从 0 起的项序号，错误信息带从 1 起的中文项号。
    """
    where = f"第 {index + 1} 项"
    if not isinstance(item, dict):
        raise ValidationError(f"{where}必须为 JSON 对象")
    if "predicates" not in item:
        raise ValidationError(f"{where}缺少字段: predicates")
    extra = sorted(
        set(item) - {"predicates", "challenge", "expires_in"}
    )
    if extra:
        raise ValidationError(
            f"{where}含多余字段: {', '.join(extra)}"
        )
    kwargs: Dict[str, Any] = {"predicates": item["predicates"]}
    if "challenge" in item:
        challenge = item["challenge"]
        if not isinstance(challenge, str) or not challenge:
            raise ValidationError(
                f"{where}字段 challenge 必须为非空字符串"
            )
        if len(challenge) > 256:
            raise ValidationError(
                f"{where}字段 challenge 按 Unicode 码点不能超过 256"
            )
        kwargs["challenge"] = challenge
    if "expires_in" in item:
        expires_in = item["expires_in"]
        if not isinstance(expires_in, int) or isinstance(
            expires_in, bool
        ):
            raise ValidationError(
                f"{where}字段 expires_in 必须为整数"
            )
        if not 1 <= expires_in <= 86400:
            raise ValidationError(
                f"{where}字段 expires_in 须在 1 到 86400 之间"
            )
        kwargs["expires_in"] = expires_in
    return kwargs

def _post_prove_batch(
    self, tenant: str, credential_id: str
) -> None:
    # 批量谓词证明：请求体须恰为 {"items": [项...]}，数组非空
    # 且不超过 50 项。外层缺失/非数组/空/超限、项非对象、缺
    # predicates 或多余字段、challenge/expires_in 类型或范围非法
    # 一律 400 且不写入任何记录；所有项的请求级校验全部通过后
    # 才查凭证：路径凭证未知（含他租户）404；其后按签发 DID
    # 停用 409、签发密钥吊销 400、凭证暂停 409 的顺序拒绝，
    # 均不留证明或审计；项内 predicates 语义（结构/路径/运算/
    # 数值、重复与祖先重叠）由 store 逐项校验，任一失败整体
    # 回滚。成功 201 仅返回 {"proofs": [...]}，与输入等长、同序，
    # 每项键序与单项 prove 完全一致；缺省 challenge 与有效期逐项
    # 独立生成。全部证明记录与每条 proof.created 审计同一次原子
    # 提交，落盘失败 500 且不留下部分记录，审计序号不前进。
    data = self._read_json()
    if "items" not in data:
        raise ValidationError("缺少字段: items")
    extra = sorted(set(data) - {"items"})
    if extra:
        raise ValidationError(f"多余字段: {', '.join(extra)}")
    items = data["items"]
    if not isinstance(items, list):
        raise ValidationError("字段 items 必须为数组")
    if not items:
        raise ValidationError("items 数组不能为空")
    if len(items) > 50:
        raise ValidationError(
            "items 数组不能超过 50 项"
            f"（当前 {len(items)} 项）"
        )
    kwargs_list = [
        self._validate_prove_item(item, index)
        for index, item in enumerate(items)
    ]
    records = store.create_proofs_batch(
        tenant, credential_id, kwargs_list
    )
    self._send_json(
        201,
        {
            "proofs": [
                self._proof_payload(record) for record in records
            ]
        },
    )

def _post_verify_proof(self, tenant: str, proof_id: str) -> None:
    # 与凭证/演示 verify 相同的公开错误协议：任何“验签失败”都
    # 返回 200 + {"valid": false, "reason": "<非空中文原因>"}，
    # 绝不返回 404/500。失败不消费；并发仅一次成功并持久化。
    try:
        length = int(self.headers.get("Content-Length") or 0)
        raw = self.rfile.read(length) if length > 0 else b""
    except (ValueError, TypeError):
        self._send_invalid("请求体缺失或长度声明非法")
        return
    except Exception:  # noqa: BLE001
        self._send_invalid("请求体读取失败")
        return
    if not raw:
        self._send_invalid("请求体缺失")
        return
    try:
        data = json.loads(raw.decode("utf-8"))
    except UnicodeDecodeError:
        self._send_invalid("请求体不是合法 UTF-8 文本")
        return
    except json.JSONDecodeError:
        self._send_invalid("请求体不是合法 JSON")
        return
    if not isinstance(data, dict):
        self._send_invalid("请求体必须为 JSON 对象")
        return
    if "proof" not in data:
        self._send_invalid("请求缺少字段: proof")
        return
    extra = sorted(set(data) - {"proof", "challenge"})
    if extra:
        self._send_invalid(f"请求含多余字段: {', '.join(extra)}")
        return
    challenge = CHALLENGE_UNSET
    if "challenge" in data:
        challenge = data["challenge"]
        if not isinstance(challenge, str) or not challenge:
            self._send_invalid(
                "请求字段 challenge 必须为非空字符串"
            )
            return

    try:
        valid, reason = store.verify_proof(
            tenant, proof_id, data["proof"], challenge
        )
    except Exception:  # noqa: BLE001 验签失败绝不暴露内部细节
        self._send_invalid("验签过程发生内部错误")
        return
    payload: Dict[str, Any] = {"valid": valid}
    if not valid:
        payload["reason"] = reason or "验签失败"
    self._send_json(200, payload)

