            bucket["proofs"].get(proof_id)
            if bucket is not None else None
        )
        if row is None:
            return False, f"证明不存在: {proof_id}"

        if challenge is CHALLENGE_UNSET:
            return False, "请求缺少字段: challenge"

        # 绑定证明按存储记录是否含 holder_did 判定。
        is_holder_bound = "holder_did" in row
        expected_keys = {
            "proof_id",
            "credential_id",
            "issuer_did",
            "issuer_key_version",
            "predicates",
            "results",
            "challenge",
            "expires_at",
            "proof",
        }
        submitted_keys = set(proof)
        if is_holder_bound:
            # 绑定证明删掉任一持有者字段 -> 持有者绑定校验失败；
            # 未绑定记录附加绑定字段在下面的未绑定分支处理。
            missing_holder = holder_fields - submitted_keys
            extra_keys = submitted_keys - (expected_keys | holder_fields)
            if missing_holder or extra_keys:
                return False, HOLDER_BINDING_FAIL_REASON
        elif submitted_keys & holder_fields:
            # 未绑定记录不允许附加任何持有者字段。
            return False, HOLDER_BINDING_FAIL_REASON
        elif submitted_keys != expected_keys:
            return False, (
                "锚定校验失败: proof 字段集合与存储记录不一致"
            )
